// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.prank(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        c.DrugDealer();
        address other = address(0x123);
        vm.prank(other);
        bool ok;
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.prank(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Reference should succeed on second call by CEO");
    }
}
